<template><div class="demo-shell"><aside class="demo-sidebar"><router-link to="/dashboard"><img src="/branding/xinggui-logo.png" alt="星轨智评"/></router-link><span class="sidebar-caption">五育成长评价 · 演示工作区</span><nav aria-label="主导航"><router-link v-for="item in navigation" :key="item.path" :to="item.path"><span>{{item.symbol}}</span>{{item.label}}</router-link></nav><div class="sidebar-end">让评价有依据<br/>让成长有方向</div></aside><div class="demo-body"><header><div><b>{{user.displayName}}</b><span class="header-role">{{user.roleText}}</span></div><div class="header-actions"><button @click="reset">重置示例</button><button @click="switchRole">切换身份 ↗</button></div></header><div class="demo-banner"><strong>独立演示版</strong><span>使用示例数据 · 操作仅保存在当前浏览器 · 未连接真实数据库和 AI</span></div><main><router-view :key="$route.fullPath"/></main><footer>星轨智评 XINGGUI <span>示例成绩和规则仅用于功能体验</span></footer></div></div></template>
<script setup>
import {computed} from 'vue';import {useRouter} from 'vue-router';import {ElMessageBox} from 'element-plus';import {useUserStore} from '@/stores/user';import {resetState} from './data.js';
const user=useUserStore();const router=useRouter();const isStudent=computed(()=>user.role==='student');
const navigation=computed(()=>[{path:'/dashboard',label:'演示总览',symbol:'◈'},{path:'/work-items',label:'我的待办与提醒',symbol:'◷'},...(user.role==='class_admin'?[{path:'/policy-desk',label:'制度问答与原文',symbol:'▧'},{path:'/campus-activities',label:'校园活动与实践机会',symbol:'◷'}]:[]),...(isStudent.value?[{path:'/my-applications',label:'我的申报',symbol:'▤'},{path:'/apply',label:'申报加分',symbol:'＋'},{path:'/rule-guide',label:'模块规则与指引',symbol:'≡'},{path:'/policy-desk',label:'制度问答与原文',symbol:'▧'},{path:'/campus-activities',label:'校园活动与实践机会',symbol:'◷'}]:[{path:'/approval',label:'材料审核工作台',symbol:'✓'}]),{path:'/evaluation',label:'综测结果与解释',symbol:'◇'},{path:'/growth-plan',label:'成长行动计划',symbol:'↗'},...(user.role==='college_admin'?[{path:'/evaluation-config',label:'综测配置与试算',symbol:'⚙'},{path:'/guidance-resources',label:'制度与活动发布',symbol:'▤'}]:[])]);
async function switchRole(){await user.logout({notifyServer:false});router.push('/login');}
async function reset(){try{await ElMessageBox.confirm('将清除当前浏览器中的演示操作，恢复初始示例。','重置演示数据',{type:'warning',confirmButtonText:'重置',cancelButtonText:'取消'});resetState();router.replace('/dashboard');}catch{}}
</script>
<style scoped>
.demo-shell{min-height:100vh;background:#f4f7fb;color:#1f3655;display:grid;grid-template-columns:224px minmax(0,1fr);}.demo-sidebar{padding:28px 18px;border-right:1px solid #dfe8f3;background:#fff;position:sticky;top:0;height:100vh;overflow-y:auto;display:flex;flex-direction:column;}.demo-sidebar img{width:158px;margin:0 10px;}.sidebar-caption{font-size:11px;color:#8091a7;margin:20px 10px 26px;}.demo-sidebar nav{display:flex;flex-direction:column;gap:7px;}.demo-sidebar nav a{display:flex;align-items:center;gap:12px;text-decoration:none;padding:13px;border-radius:10px;color:#61728a;font-size:13px;}.demo-sidebar nav a>span{width:19px;font-size:18px;color:#7891b1;}.demo-sidebar nav a.router-link-active{background:#eaf3ff;color:#2274cb;font-weight:650;}.sidebar-end{margin:auto 10px 4px;font-size:12px;line-height:1.9;color:#9aa8b8;}.demo-body{min-width:0;}header{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:18px 30px;background:#fff;border-bottom:1px solid #e2eaf4;font-size:13px;}.header-role{color:#8392a6;font-size:11px;margin-left:12px;}.header-actions{display:flex;gap:18px;}.header-actions button{border:0;background:transparent;font-size:12px;color:#2876ca;cursor:pointer;padding:4px;}.demo-banner{display:flex;flex-wrap:wrap;gap:12px;padding:10px 30px;font-size:11px;background:#eff7ff;color:#617992;line-height:1.8;}.demo-banner strong{color:#216bb4;}main{padding:28px;max-width:1600px;margin:auto;min-height:70vh;}footer{padding:20px 28px;color:#8a99ad;font-size:11px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;}button:focus-visible{outline:2px solid #277ad7;outline-offset:4px;}@media(max-width:900px){.demo-shell{grid-template-columns:minmax(0,1fr);}.demo-sidebar{height:auto;position:static;padding:16px 20px;}.demo-sidebar img{width:120px;margin:0;}.sidebar-caption,.sidebar-end{display:none;}.demo-sidebar nav{flex-direction:row;overflow-x:auto;margin-top:14px;padding-bottom:4px;}.demo-sidebar nav a{white-space:nowrap;padding:9px 12px;}.demo-sidebar nav a span{display:none;}header{padding:16px 20px;}main{padding:20px;}}@media(max-width:520px){main{padding:16px 10px;}.demo-banner{padding:10px 16px;gap:4px;}.demo-banner span{display:block;}header{padding:14px 16px;align-items:flex-start;}.header-role{display:block;margin:5px 0 0;}.header-actions{gap:9px;}}
</style>
